import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";var i=JSON.parse(`{"title":"How to get your Form ID for the CHEFS plugin","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-chefs-embed/user/how-to-get-your-form-id-for-the-chefs-plugin.md","filePath":"content/plugins/bcew-chefs-embed/user/how-to-get-your-form-id-for-the-chefs-plugin.md"}`),a={name:`content/plugins/bcew-chefs-embed/user/how-to-get-your-form-id-for-the-chefs-plugin.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="how-to-get-your-form-id-for-the-chefs-plugin" tabindex="-1">How to get your Form ID for the CHEFS plugin <a class="header-anchor" href="#how-to-get-your-form-id-for-the-chefs-plugin" aria-label="Permalink to “How to get your Form ID for the CHEFS plugin”">​</a></h1><p>Log in to the CHEFS service portal at <a href="https://submit.digital.gov.bc.ca/app" target="_blank" rel="noreferrer">https://submit.digital.gov.bc.ca/app</a>.</p><h2 id="get-your-form-id" tabindex="-1">Get your Form ID <a class="header-anchor" href="#get-your-form-id" aria-label="Permalink to “Get your Form ID”">​</a></h2><ol><li>Go to <strong>My Forms</strong> and select your form.</li><li>Click <strong>Manage</strong>, then click <strong>Share form</strong> in the top right.</li><li>Copy the Form ID from the URL. For example, in <code>https://submit.digital.gov.bc.ca/app/form/submit?f=43cfb894-a0cf-4bef-8026-7c8001e3cdf5</code>, the Form ID is <code>43cfb894-a0cf-4bef-8026-7c8001e3cdf5</code>.</li></ol><p>You can also copy the Form ID from the <code>f</code> value in the URL on the form&#39;s <strong>Manage</strong> page.</p><p>Make sure the form has been published in CHEFS before adding it to WordPress. The WordPress integration requires a published version to load the form; a form that only has draft versions cannot be embedded.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};